import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    static int n, m;
    static int[] bad;
    static long ans = 0;

    static void solve(int idx, int mask) {
        if (idx == n) {
            ans++;
            return;
        }

        // Opção 1: não incluir o ingrediente idx
        solve(idx + 1, mask);

        // Opção 2: incluir o ingrediente idx, se compatível com os já escolhidos
        if ((bad[idx] & mask) == 0) {
            solve(idx + 1, mask | (1 << idx));
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = null;

        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        st = new StringTokenizer(line);
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        bad = new int[n];

        for (int i = 0; i < m; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;
            st = new StringTokenizer(line);
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            bad[u] |= (1 << v);
            bad[v] |= (1 << u);
        }

        solve(0, 0);

        // Subtrai 1 correspondente ao conjunto vazio
        System.out.println(ans - 1);
    }
}
